<script setup lang="ts">
import { Download, ArrowLeftRight, Clock3, Equal, UsersRound } from '@lucide/vue'
import { formatHours, prettyDate } from '../domain/calendar'
import { applySwap, type SwapSuggestion } from '../domain/commands'
import { getFairnessProposal } from '../services/fairness-proposal'
import { downloadText, rosterCsv } from '../services/exports'
const w = useWorkspace(), suggestion = ref<SwapSuggestion | null>(null), calculating = ref(false)
const { notify } = useNotifications()
const total = computed(() => w.summaries.value.reduce((sum, r) => sum + r.knownHours, 0))
const name = (id: string) => w.data.value?.doctors.find(d => d.id === id)?.name ?? ''
watch(w.activeMonth, () => { suggestion.value = null })
async function suggest() {
  if (!w.data.value || !w.plan.value) return
  calculating.value = true
  await nextTick()
  try {
    suggestion.value = await getFairnessProposal(w.data.value, w.activeMonth.value)
    if (!suggestion.value) notify(w.balance.value.spread === 0 ? 'Jam dokter rotasi sebulan penuh sudah sama.' : 'Belum ada pertukaran yang memperbaiki pemerataan tanpa menambah benturan. Periksa jadwal secara manual.')
  } catch (e) { notify((e as Error).message, true) }
  finally { calculating.value = false }
}
async function apply() { if (!suggestion.value) return; const s = suggestion.value; if (await w.mutate(data => applySwap(data, w.activeMonth.value, s, w.role.value), `Pertukaran dinas ${s.date}: ${name(s.doctorA)} / ${name(s.doctorB)}`)) suggestion.value = null }
function exportCsv() { if (w.data.value && w.plan.value) downloadText(rosterCsv(w.data.value, w.plan.value), `Rekap_${w.activeMonth.value}.csv`, 'text/csv;charset=utf-8') }
</script>
<template>
  <PageHeading title="Rekap jam kerja" subtitle="Bandingkan jam berdasarkan ketersediaan dokter, dengan cuti dan tanggal mulai tetap terpisah." eyebrow="Beban kerja"><MonthSelect/><button class="btn btn-secondary" :disabled="!w.plan.value" @click="exportCsv"><Download :size="16"/>Ekspor CSV</button></PageHeading>
  <template v-if="w.plan.value"><div class="mb-6 grid gap-4 sm:grid-cols-3"><div v-for="card in [{ label: 'Total jam seluruh dokter', value: formatHours(total), note: 'Dihitung dari isian jadwal', icon: Clock3 }, { label: 'Selisih rotasi sebulan penuh', value: formatHours(w.balance.value.spread), note: `${w.balance.value.rows.length} dokter dibandingkan`, icon: Equal }, { label: 'Rentang jam rotasi penuh', value: `${formatHours(w.balance.value.min)}–${formatHours(w.balance.value.max)}`, note: 'Ketersediaan yang sama', icon: UsersRound }]" :key="card.label" class="panel p-5"><div class="mb-4 flex items-center justify-between text-xs text-slate-500">{{ card.label }}<component :is="card.icon" :size="18" class="text-brand-600"/></div><p class="text-3xl font-semibold tracking-tight">{{ card.value }}<span class="ml-1.5 text-xs font-normal text-slate-400">jam</span></p><p class="mt-3 text-[11px] text-slate-400">{{ card.note }}</p></div></div>
    <div class="panel overflow-hidden"><div class="scrollbar-thin overflow-x-auto"><table class="w-full text-left text-xs"><thead class="table-head"><tr><th class="px-5 py-4">Dokter</th><th class="px-4 py-4 text-right">Jam kerja</th><th class="px-4 py-4 text-center">Dinas</th><th class="px-4 py-4 text-center">Dinas 12 jam</th><th class="px-4 py-4 text-center">Libur</th><th class="px-4 py-4 text-center">Cuti</th><th class="px-4 py-4 text-center">Belum mulai</th><th class="px-4 py-4">Keterangan</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="r in w.summaries.value" :key="r.doctor.id" class="hover:bg-slate-50/70"><td class="whitespace-nowrap px-5 py-4 font-semibold">{{ r.doctor.name }}</td><td class="px-4 py-4 text-right font-semibold tabular-nums text-brand-700">{{ formatHours(r.totalHours) }}</td><td class="px-4 py-4 text-center">{{ r.workDays }}</td><td class="px-4 py-4 text-center">{{ r.longDays }}</td><td class="px-4 py-4 text-center text-slate-500">{{ r.offDays }}</td><td class="px-4 py-4 text-center text-slate-500">{{ r.leaveDays }}</td><td class="px-4 py-4 text-center text-slate-500">{{ r.notStartedDays }}</td><td class="min-w-40 px-4 py-4"><span class="tag" :class="r.emptyDays ? 'bg-amber-50 text-amber-700' : r.comparable ? 'bg-brand-50 text-brand-700' : 'bg-slate-100 text-slate-500'">{{ r.emptyDays ? `${r.emptyDays} hari kosong` : r.comparable ? 'Rotasi sebulan penuh' : r.doctor.unit === 'anak' ? 'Khusus ruang anak' : r.leaveDays ? 'Memiliki cuti' : 'Dokter baru' }}</span></td></tr></tbody><tfoot><tr class="border-t border-brand-100 bg-brand-50"><td class="px-5 py-4 font-semibold">Total</td><td class="px-4 py-4 text-right font-bold text-brand-800">{{ formatHours(total) }}</td><td colspan="6"/></tr></tfoot></table></div></div>
    <div class="mt-6 grid gap-5 lg:grid-cols-[1.5fr_1fr]"><section class="panel p-6"><h2 class="text-sm font-semibold">Cara membaca pemerataan</h2><p class="mt-3 text-sm leading-relaxed text-slate-500">Dokter rotasi yang tersedia sepanjang bulan dibandingkan dalam kelompok yang sama. Dokter yang cuti, baru bergabung, atau khusus ruang anak memiliki kondisi berbeda; jam mereka tetap dihitung dari dinas yang dijalankan.</p><p class="mt-3 text-xs text-slate-400">Libur, cuti, dan belum mulai bernilai 0 jam. Hari kosong belum dianggap sebagai libur. Dinas yang melewati tengah malam dicatat pada tanggal mulai.</p></section><section class="panel p-6"><h2 class="text-sm font-semibold">Saran pertukaran dinas</h2><p class="mt-3 text-xs leading-relaxed text-slate-500">Cari satu pertukaran yang menurunkan selisih jam tanpa menambah benturan pola, cuti, atau jeda dinas. Saran ditinjau sebelum diterapkan.</p><button class="btn btn-secondary mt-5 w-full" :disabled="!w.canEdit.value || w.plan.value.locked || calculating" @click="suggest"><ArrowLeftRight :size="16"/>{{ calculating ? 'Menghitung…' : 'Cari saran pemerataan' }}</button></section></div>
  </template><div v-else class="panel p-8 text-sm text-slate-500">Buat jadwal terlebih dahulu untuk melihat rekap.</div>
  <AppModal v-if="suggestion" title="Saran pertukaran dinas" @close="suggestion = null"><p class="text-sm text-slate-500">{{ prettyDate(suggestion.date) }}</p><div class="mt-5 space-y-3"><div class="rounded-xl bg-slate-50 p-4"><p class="text-sm font-semibold">{{ name(suggestion.doctorA) }}</p><p class="mt-1 text-xs text-slate-500">{{ suggestion.codeA }} → {{ suggestion.codeB }}</p></div><div class="rounded-xl bg-slate-50 p-4"><p class="text-sm font-semibold">{{ name(suggestion.doctorB) }}</p><p class="mt-1 text-xs text-slate-500">{{ suggestion.codeB }} → {{ suggestion.codeA }}</p></div><p class="rounded-xl bg-brand-50 p-4 text-sm text-brand-800">Selisih kelompok: {{ suggestion.spreadBefore }} → {{ suggestion.spreadAfter }} jam.</p></div><div class="mt-6 flex justify-end gap-2"><button class="btn btn-secondary" @click="suggestion = null">Batal</button><button class="btn btn-primary" :disabled="w.saving.value" @click="apply">Terapkan pertukaran</button></div></AppModal>
</template>
